import re

def process_css_text(css_text, base_url, fetch_asset_fn, no_images=False, no_fonts=False):
    # 1. If no_fonts, strip @font-face blocks
    if no_fonts:
        # Regex to match @font-face { ... }
        css_text = re.sub(r'@font-face\s*\{[^}]*\}', '', css_text)

    # 2. Process @import rules
    # Matches @import "..." or @import '...' or @import url(...)
    def import_replacer(match):
        full = match.group(0)
        import_url = match.group(1) or match.group(2) or match.group(3)
        import_url = import_url.strip('\'"')
        if import_url.startswith('data:'):
            return full
        # Fetch imported CSS
        data_url = fetch_asset_fn(import_url, base_url, is_css=True)
        if data_url:
            return f'@import "{data_url}";'
        return full

    css_text = re.sub(r'@import\s+(?:"([^"]+)"|\'([^\']+)\'|url\(([^)]+)\))\s*;?', import_replacer, css_text)

    # 3. Process url(...) declarations
    def url_replacer(match):
        raw_url = match.group(1).strip('\'" \t\r\n')
        if raw_url.startswith('data:'):
            return f'url("{raw_url}")'

        hash_part = ""
        if '#' in raw_url:
            raw_url, hash_part = raw_url.split('#', 1)
            hash_part = '#' + hash_part

        if no_images:
            trans_png = "data:image/png,%89PNG%0D%0A%1A%0A%00%00%00%0DIHDR%00%00%00%0D%00%00%00%0D%08%04%00%00%00%D8%E2%2C%F7%00%00%00%11IDATx%DAcd%C0%09%18G%A5%28%96%02%00%0A%F8%00%0E%CB%8A%EB%16%00%00%00%00IEND%AEB%60%82"
